604	    );
605	  }
606	
607	  // done
608	  if (LIVE_STAGES.has(stage.id)) {
609	    return (
610	      <section className="output-zone">
611	        <div className="output-meta">
612	          <span>Saved to vault</span>
613	          <div className="output-meta-actions">
614	            <button
615	              className="btn-icon"
616	              title="Copy path"
617	              onClick={() => navigator.clipboard.writeText(jobResult?.primary_path || "")}>
618	              <Icon.Copy size={14} />
619	            </button>
620	          </div>
621	        </div>
622	        <OutputBrowser result={jobResult} />
623	      </section>
624	    );
625	  }
626	
627	  const renderer = OUTPUTS[stage.id];
628	  return (
629	    <section className="output-zone">
630	      <div className="output-meta">
631	        <span>Generated 2 min ago &#183; 1,240 tokens &#183; via Claude Sonnet</span>
632	        <div className="output-meta-actions">
633	          <button className="btn-icon" title="Copy"><Icon.Copy size={14} /></button>
634	          <button className="btn-icon" title="Save to Vault"><Icon.Save size={14} /></button>
635	          <button className="btn-icon" title="Share"><Icon.Share2 size={14} /></button>
636	        </div>
637	      </div>
638	      <div className="output-body md">
639	        {renderer ? renderer() : <p>No output renderer yet.</p>}
640	      </div>
641	    </section>
642	  );
643	}
644	
645	function HistoryDrawer({ stage, open, onClose, folder }) {
646	  const [items, setItems] = useState([]);
647	  const [loading, setLoading] = useState(false);
648	  const [selected, setSelected] = useState(null);
649	
650	  /* eslint-disable react-hooks/set-state-in-effect */
651	  useEffect(() => {
652	    if (!open || !folder) return;
653	    setLoading(true);
654	    setSelected(null);
655	    getRecent(folder, 20)
656	      .then(setItems)
657	      .catch(() => setItems([]))
658	      .finally(() => setLoading(false));
659	  }, [open, folder]);
660	  /* eslint-enable react-hooks/set-state-in-effect */
661	
662	  return (
663	    <>
664	      <div className={"drawer-backdrop" + (open ? " open" : "")} onClick={onClose} />
665	      <aside className={"drawer" + (open ? " open" : "")} style={{ "--stage-color": stage.color }}>
666	        <div className="drawer-handle" aria-hidden="true">
667	          <Icon.History size={16} />
668	          <span className="drawer-handle-text">History</span>
669	          {items.length > 0 && <span className="drawer-handle-count">{items.length}</span>}
670	        </div>
671	        <div className="drawer-content">
672	          <header className="drawer-header">
673	            <div>
674	              <div className="drawer-eyebrow">{stage.label}</div>
675	              <h2 className="drawer-title">Run history</h2>
676	            </div>
677	            <button className="btn-icon" onClick={onClose} title="Close"><Icon.X size={14} /></button>
678	          </header>
679	          <div className="drawer-body">
680	            {selected ? (
681	              <>
682	                <button className="btn btn-ghost" onClick={() => setSelected(null)} style={{ marginBottom: 12 }}>
683	                  <Icon.ArrowLeft size={12} />
684	                  Back
685	                </button>
686	                <MarkdownViewer path={selected} />
687	              </>
688	            ) : loading ? (
689	              <>
690	                <div className="skeleton skeleton-row long" />
691	                <div className="skeleton skeleton-row medium" />
692	              </>
693	            ) : items.length === 0 ? (
694	              <p style={{ color: "var(--text-muted)", fontSize: 13 }}>No history yet.</p>
695	            ) : (
696	              items.map((it) => (
697	                <div key={it.path} className="history-item" style={{ cursor: "pointer" }} onClick={() => setSelected(it.path)}>
698	                  <div className="history-time">{it.modified || ""}</div>
699	                  <div className="history-prompt">{it.name}</div>
700	                </div>
701	              ))
702	            )}
703	          </div>
704	        </div>
705	      </aside>
706	    </>
707	  );
708	}
709	
710	export default StageWorkspace;
